"""Build eng5z.py from ../t20_R2/eng5.py: the same engine, with ONE extension: an orbit of X_2 may be an inner pair of N(p).
Convention: the candidate orbit {s, sigma s} is inner  <=>  p (vertex 20) is in its tuple N0. Then s ~ sigma s (zz = 1) and both
are adjacent to p. Every exact test of the engine already takes zz (Node.budget_fail, Node.psd_fail, Node.child); only run()
hard-coded zz = 0. The float selection (evaluate_f) is written for zz = 0, so for an inner candidate it is bypassed: its budget
and its semidefiniteness are decided by the exact routines directly. Each replacement below must match exactly once."""
import os
HERE = os.path.dirname(os.path.abspath(__file__))
s = open(os.path.join(HERE, "..", "t20_R2", "eng5.py"), encoding="utf-8").read()
REPL = [
 ("    single = {}\n",
  "    def zzof(N0):\n        return 1 if 20 in N0 else 0\n\n    single = {}\n"),
 ("            if root.budget_fail(row, 0):\n                stats.add(\"single_budget\"); r = False\n            elif root.psd_fail(row, 0, stats) is not None:",
  "            if root.budget_fail(row, zzof(N0)):\n                stats.add(\"single_budget\"); r = False\n            elif root.psd_fail(row, zzof(N0), stats) is not None:"),
 ("            nd = root.child(base_row(o[0], o[1], o[2], nb), 0)",
  "            nd = root.child(base_row(o[0], o[1], o[2], nb), zzof(o[2]))"),
 ("            if nd.budget_fail(row, 0):\n                stats.add(\"pair_budget\"); r = False\n            elif nd.psd_fail(row, 0, stats) is not None:",
  "            if nd.budget_fail(row, zzof(o2[2])):\n                stats.add(\"pair_budget\"); r = False\n            elif nd.psd_fail(row, zzof(o2[2]), stats) is not None:"),
 ("            if bb[a]:\n                if nd.budget_fail(R[a], 0):          # int64 recount\n                    stats.add(\"pair_budget\"); r = False\n                else:\n                    stats.add(\"float_int_budget_mismatch\")",
  "            z2 = zzof(o2[2])\n            if bb[a] or z2:\n                if nd.budget_fail(R[a], z2):          # int64 recount (always, for an inner orbit)\n                    stats.add(\"pair_budget\"); r = False\n                elif not z2:\n                    stats.add(\"float_int_budget_mismatch\")"),
 ("        for a, cd in enumerate(cands):\n            if bb[a]:\n                if node.budget_fail(R[a], 0):        # int64 recount of the violated budget\n                    rej_b[t] += 1\n                    continue\n                stats.add(\"float_int_budget_mismatch\")\n            if pb[a]:\n                bi = int(fb[a])\n                r = node.psd_cert_block(bi, vc[bi][0][a], vc[bi][1], stats)\n                if r is None:\n                    r = node.psd_fail(R[a], 0, stats)\n",
  "        for a, cd in enumerate(cands):\n            zc = zzof(cd[1])\n            if bb[a] or zc:\n                if node.budget_fail(R[a], zc):       # int64 recount of the violated budget (always, for an inner orbit)\n                    rej_b[t] += 1\n                    continue\n                if not zc:\n                    stats.add(\"float_int_budget_mismatch\")\n            if pb[a] or zc:\n                if zc:\n                    r = node.psd_fail(R[a], 1, stats)\n                else:\n                    bi = int(fb[a])\n                    r = node.psd_cert_block(bi, vc[bi][0][a], vc[bi][1], stats)\n                    if r is None:\n                        r = node.psd_fail(R[a], 0, stats)\n"),
 ("                        ch = node.child(R[a], 0)\n                        certf.write(",
  "                        ch = node.child(R[a], zc)\n                        certf.write("),
 ("                    continue\n                stats.add(\"float_selected_but_not_rejected\")\n            todo.append(a)",
  "                    continue\n                if not zc:\n                    stats.add(\"float_selected_but_not_rejected\")\n            todo.append(a)"),
 ("            kept[t] += 1\n            ch = node.child(R[a], 0)",
  "            kept[t] += 1\n            ch = node.child(R[a], zzof(N0))"),
 ("\"setwise\": setwise, \"engine\": \"eng5\",", "\"setwise\": setwise, \"engine\": \"eng5z\","),
]
for old, new in REPL:
    assert s.count(old) == 1, "pattern not found exactly once:\n" + old
    s = s.replace(old, new)
s = "# eng5z.py = eng5.py with inner orbits of X_2 allowed (generated by mk_eng5z.py; do not edit by hand)\n" + s
open(os.path.join(HERE, "eng5z.py"), "w", encoding="utf-8", newline="\n").write(s)
print("eng5z.py written: %d replacements" % len(REPL))
